sch = json.load(open(schema))
fields = {t["name"]: [f["name"] for f in t["fields"]] for t in sch["tables"]}

problems = []
counts = {}
for tname, rows in d["tables"].items():
    counts[tname] = len(rows)
    for i, row in enumerate(rows):
        missing = [f for f in fields[tname] if f not in row]
        extra = [f for f in row if f not in fields[tname]]
        if missing: problems.append(f"{tname}[{i}] missing fields {missing}")
