            if not isinstance(cell, dict) or set(cell.keys()) != {"value", "span"}:
                problems.append(f"{tname}[{i}].{f} bad cell {cell}")
                continue
            sp = cell["span"]
            spans = sp if isinstance(sp, list) else ([sp] if sp is not None else [])
            if cell["value"] not in (None, "not reported") and f not in ("hpo_label_candidate", "hpo_id_candidate", "checklist_feature"):
                if not spans:
                    problems.append(f"{tname}[{i}].{f} value without span: {cell['value']!r}")
