                if s not in text:
                    problems.append(f"{tname}[{i}].{f} SPAN NOT FOUND: {s!r}")
                if len(s) > 300:
                    problems.append(f"{tname}[{i}].{f} span too long ({len(s)}): {s[:60]!r}")

# enums
enum = {}
for t in sch["tables"]:
    for f in t["fields"]:
        if f.get("enum_values"):
            enum[(t["name"], f["name"])] = f["enum_values"]
for tname, rows in d["tables"].items():
    for i, row in enumerate(rows):
        for f, cell in row.items():
            key = (tname, f)
            if key in enum and cell["value"] not in enum[key] + [None]:
                problems.append(f"{tname}[{i}].{f} bad enum {cell['value']!r}")

# checklist completeness
CL = ["oral ulcers","genital ulcers","gastrointestinal ulcers or inflammation","recurrent fever",
"arthritis or arthralgia","uveitis or other ocular inflammation","skin lesions (rash, folliculitis, erythema nodosum)",
"autoimmune thyroiditis","type 1 diabetes","autoimmune hepatitis","cytopenia (autoimmune)",
"lymphoproliferation or lymphadenopathy","central nervous system involvement","recurrent infections",
"elevated inflammatory markers (CRP/ESR)","autoantibodies (ANA/other)","growth failure",
"pericarditis or other serositis","interstitial lung disease","vasculitis"]
labels = [r["individual_label_in_paper"]["value"] for r in d["tables"]["individuals"]]
for lab in labels:
    got = [r["checklist_feature"]["value"] for r in d["tables"]["phenotype_checklist"] if r["individual_label_in_paper"]["value"] == lab]
    if sorted(got) != sorted(CL):
        problems.append(f"checklist for {lab}: {len(got)} rows; diff={set(CL) ^ set(got)}")
# label consistency
ind_labels = set(labels)
for tname in ("variants", "phenotypic_features", "phenotype_checklist"):
    for r in d["tables"][tname]:
        if r["individual_label_in_paper"]["value"] not in ind_labels:
            problems.append(f"{tname} unknown label {r['individual_label_in_paper']['value']!r}")

print("rows per table:", counts)
print("individuals:", len(labels), labels)
print("problems:", len(problems))
for p in problems:
    print(" -", p)
